CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 NUMERIC CHECK(c0 IS NULL OR length(c0) < 40), c1, c2 VARCHAR(10) COLLATE NOCASE, c3 TEXT NOT NULL DEFAULT 0, c4 TEXT DEFAULT 'd');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(574.81, x'bde9735c', -321, 0, x'620f');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('señor', -584, NULL, '0x1F', x'6224b696150d');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL NOT NULL DEFAULT 0, c1 INTEGER, c2 TEXT COLLATE NOCASE, c3 INT UNIQUE, c4 INTEGER);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 VARCHAR(10) NOT NULL DEFAULT 0, c1 TEXT UNIQUE, c2  COLLATE NOCASE, c3 BLOB, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES(-525, 'x_y', 0, 3, 2);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES(0, 'Ελλάδα', 'MU', 'eta', 1);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES(-4, 4, 545.2, NULL, 5);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES(x'a3fa00e70c', 1, 3, x'8a', 8);
SELECT length('日本'), upper('日本'), lower('日本'), substr('日本', -3, 4), instr('日本', 'iota'), replace('日本', '', '_'), trim('日本'), ltrim('日本', 'ab'), hex('日本'), quote('日本'), unicode('日本'), '日本' LIKE 'a%', '日本' GLOB '?', char(88, 801), '日本' || 'iota', '日本' < 'iota', '日本' = 'iota' COLLATE NOCASE;
SELECT length('theta'), upper('theta'), lower('theta'), substr('theta', 2, 2), instr('theta', 'rho'), replace('theta', 'a', 'XY'), trim('theta'), ltrim('theta', 'ab'), hex('theta'), quote('theta'), unicode('theta'), 'theta' LIKE '%a_', 'theta' GLOB '*', char(74, 997), 'theta' || 'rho', 'theta' < 'rho', 'theta' = 'rho' COLLATE NOCASE;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', 2, 4), instr('upsilon', 'xi'), replace('upsilon', '', ''), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE '%a_', 'upsilon' GLOB '*', char(85, 582), 'upsilon' || 'xi', 'upsilon' < 'xi', 'upsilon' = 'xi' COLLATE NOCASE;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', 2, 2), instr('upsilon', '-7'), replace('upsilon', 'a', 'XY'), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE '%a_', 'upsilon' GLOB '*', char(78, 648), 'upsilon' || '-7', 'upsilon' < '-7', 'upsilon' = '-7' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', 0, 0), instr('café', 'pi'), replace('café', '', '_'), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%é%', 'café' GLOB 'a*', char(75, 559), 'café' || 'pi', 'café' < 'pi', 'café' = 'pi' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', -1, 5), instr('', 'tau'), replace('', 'a', '_'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%é%', '' GLOB '*[a-m]*', char(72, 903), '' || 'tau', '' < 'tau', '' = 'tau' COLLATE NOCASE;
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', 1, 4), instr('0x1F', 'it''s'), replace('0x1F', 'é', '_'), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE 'A%', '0x1F' GLOB 'a*', char(87, 333), '0x1F' || 'it''s', '0x1F' < 'it''s', '0x1F' = 'it''s' COLLATE NOCASE;
WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, a + b FROM f WHERE n < 50) SELECT n, a FROM f ORDER BY n DESC LIMIT 5;
WITH RECURSIVE s(x) AS (SELECT 4 UNION ALL SELECT CASE WHEN x % 2 THEN 3 * x + 1 ELSE x / 2 END FROM s WHERE x <> 1) SELECT count(*), max(x), group_concat(x) FROM s;
WITH a(x) AS (VALUES(1),(2),(3)), b(y) AS (SELECT x * x FROM a) SELECT x, y FROM a, b ORDER BY x, y;
BEGIN;
UPDATE t1 SET c0 = NULL WHERE id < 6;
SAVEPOINT s1;
DELETE FROM t1 WHERE id > 3;
ROLLBACK TO s1;
SELECT count(*), count(c0) FROM t1;
ROLLBACK;
SELECT count(*) FROM t1;
COMMIT;
